suppressPackageStartupMessages({library(jsonlite);library(survival)})
a<-readRDS('work/a1.rds');cal<-readRDS('work/a2.rds');b<-readRDS('work/b_results.rds');cc<-readRDS('work/c_results.rds');dd<-readRDS('work/d_results.rds');out<-'outputs/BIOAGE-REL-01';checks<-list()
check<-function(name,test,evidence){checks[[name]]<<-list(pass=isTRUE(test),evidence=evidence);if(!isTRUE(test))stop(name)}
check('main_people_unique',!anyDuplicated(a$main$SEQN)&&nrow(a$main)==1801,'Unique SEQN=1801')
check('nine_markers_present_complete',all(complete.cases(a$main[,c(a$bm1,a$bm2)])),'All 18 visit-marker fields complete')
expected<-c(WCR=2358,LMRPCNT=2359,MVRSI=2358,RWR=2358,CRR=2332,AMR=2150,APRSI=2150,CER=2150,SGR=2150)
actual<-sapply(names(expected),function(v)sum(!is.na(a$r[[v]])))
check('repeat_nonmissing_counts_match_codebook',all(expected==actual),as.list(actual))
check('pregnant_second_excluded',!any(a$main$MARF12R==1,na.rm=T),'MARF12R=1 excluded; unknown pregnancy reported')
check('calibration_gates',all(cal$cal$status=='PASS')&&cal$kidney_n==795,as.list(setNames(cal$cal$value,cal$cal$check)))
lx<-data.frame(score=c(b$y1,b$y2),person=factor(rep(seq_along(b$y1),2)),visit=factor(rep(1:2,each=length(b$y1))))
av<-anova(lm(score~person+visit,data=lx));msr<-av['person','Mean Sq'];msc<-av['visit','Mean Sq'];mse<-av['Residuals','Mean Sq'];n<-length(b$y1);icc_alt<-(msr-mse)/(msr+mse+2*(msc-mse)/n)
mainrow<-b$rel[b$rel$group=='all'&b$rel$metric=='ICC',]
check('ICC_independent_two_way_anova',abs(icc_alt-mainrow$value)<1e-10,list(icc_from_lm_ANOVA=icc_alt,icc_closed_form=mainrow$value))
check('MDC_identity',abs(b$rel$value[b$rel$group=='all'&b$rel$metric=='MDC95']-1.96*sd(b$y2-b$y1))<1e-10,'MDC95=1.96*SD(paired difference)')
check('first_only_residual_model',b$base_n==15635&&abs(sum(residuals(b$resmod)))<1e-6,list(n_first_complete_adults=b$base_n,intercept=coef(b$resmod)[1],age_slope=coef(b$resmod)[2]))
check('precision_gate',((mainrow$ci_upper-mainrow$ci_lower)/2)<=.03,((mainrow$ci_upper-mainrow$ci_lower)/2))
check('C_bootstrap_complete',all(cc$results$bootstrap_success==2000),'All 2000 paired-person Cox bootstrap fits succeeded')
check('mortality_same_risk_set',all(cc$results$n==1801)&&all(cc$results$deaths==829),'All C results N=1801 D=829')
check('replication_pair_unique',!anyDuplicated(dd$d$SEQN)&&nrow(dd$d)==407,'415 second-exam complete adults; 407 complete pairs')
sens<-read.csv(file.path(out,'B_sensitivity.csv'));ii<-sens$status=='NOT_RUN'&sens$metric%in%c('ICC','top20_retention');sens$unit[ii]<-'proportion';sens$reason[sens$status=='NOT_RUN']<-'No paired people in stratum; contrast not identifiable';write.csv(sens,file.path(out,'B_sensitivity.csv'),row.names=FALSE,na='')
write_json(list(status='PASS',checks=checks),file.path(out,'QA.json'),pretty=TRUE,auto_unbox=TRUE,digits=16)
capture.output(sessionInfo(),file=file.path(out,'sessionInfo.txt'))
cat('All',length(checks),'aggregate and numerical QA checks passed\n')
